-- X/Twitter shadow operations; no Instagram dependencies.
alter type public.twitter_item_status add value if not exists 'shadowed';
create type public.twitter_hold_status as enum('reserved','active','outcome_unknown','settled','released');
create type public.twitter_attempt_status as enum('claimed','external_started','retry','outcome_unknown','published','failed','shadowed','cancelled');
create table public.twitter_item_holds(item_id uuid primary key references public.twitter_publication_items(id) on delete restrict,reservation_id uuid not null references public.twitter_wallet_reservations(id) on delete restrict,organization_id uuid not null references public.organizations(id) on delete restrict,amount_micros bigint not null check(amount_micros in(15000,200000)),status public.twitter_hold_status not null default 'reserved',activated_at timestamptz,resolved_at timestamptz,created_at timestamptz not null default timezone('utc',now()),updated_at timestamptz not null default timezone('utc',now()));
create table public.twitter_publication_attempts(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete restrict,item_id uuid not null references public.twitter_publication_items(id) on delete restrict,attempt_number integer not null check(attempt_number>0),worker_id text not null,idempotency_key text not null unique,status public.twitter_attempt_status not null default 'claimed',external_started_at timestamptz,finished_at timestamptz,http_status integer,provider_code text,request_id text,post_id text,retry_after_seconds integer,error_message text,evidence jsonb not null default '{}',created_at timestamptz not null default timezone('utc',now()),updated_at timestamptz not null default timezone('utc',now()),unique(item_id,attempt_number));
create table public.twitter_operation_logs(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete restrict,item_id uuid references public.twitter_publication_items(id) on delete restrict,attempt_id uuid references public.twitter_publication_attempts(id) on delete restrict,connection_id uuid references public.twitter_connections(id) on delete restrict,profile_id uuid references public.twitter_profiles(id) on delete restrict,phase text not null,http_status integer,provider_code text,request_id text,post_id text,estimated_micros bigint,settled_micros bigint,message text,metadata jsonb not null default '{}',created_at timestamptz not null default timezone('utc',now()));
create table public.twitter_worker_heartbeats(worker_name text primary key,worker_id text not null,mode text not null check(mode in('stopped','shadow','live')),last_seen_at timestamptz not null,metadata jsonb not null default '{}',updated_at timestamptz not null default timezone('utc',now()));
create table public.twitter_circuit_breakers(scope_key text primary key,state text not null check(state in('closed','open','half_open')),failure_count integer not null default 0,opened_at timestamptz,reason text,updated_at timestamptz not null default timezone('utc',now()));
create index twitter_attempts_item_idx on public.twitter_publication_attempts(item_id,created_at desc);create index twitter_logs_org_idx on public.twitter_operation_logs(organization_id,created_at desc);create unique index twitter_one_claim_per_profile_idx on public.twitter_publication_items(profile_id) where status='claimed';
create trigger twitter_item_holds_updated before update on public.twitter_item_holds for each row execute function public.set_updated_at();create trigger twitter_attempts_updated before update on public.twitter_publication_attempts for each row execute function public.set_updated_at();create trigger twitter_logs_immutable before update or delete on public.twitter_operation_logs for each row execute function public.prevent_twitter_immutable_mutation();
create or replace function public.twitter_create_item_hold() returns trigger language plpgsql security definer set search_path=public as $$declare reservation uuid;begin select pr.reservation_id into reservation from public.twitter_program_reservations pr where pr.program_id=new.program_id and pr.identity_id=new.identity_id and pr.category=new.category;if reservation is null then raise exception 'Reserva agregada X ausente.';end if;insert into public.twitter_item_holds(item_id,reservation_id,organization_id,amount_micros)values(new.id,reservation,new.organization_id,new.amount_micros);return new;end$$;
create trigger twitter_publication_item_create_hold after insert on public.twitter_publication_items for each row execute function public.twitter_create_item_hold();
insert into public.twitter_item_holds(item_id,reservation_id,organization_id,amount_micros)select i.id,pr.reservation_id,i.organization_id,i.amount_micros from public.twitter_publication_items i join public.twitter_program_reservations pr on pr.program_id=i.program_id and pr.identity_id=i.identity_id and pr.category=i.category on conflict do nothing;
create or replace function public.twitter_release_item_hold(p_item_id uuid,p_reason text,p_idempotency_key text)returns bigint language plpgsql security definer set search_path=public as $$declare h public.twitter_item_holds;r public.twitter_wallet_reservations;begin if coalesce(auth.role(),'')<>'service_role'then raise exception using errcode='42501';end if;select * into h from public.twitter_item_holds where item_id=p_item_id for update;if not found or h.status='released'then return 0;end if;if h.status in('active','outcome_unknown','settled')then raise exception using errcode='55000',message='Hold X não pode ser liberado automaticamente.';end if;select * into r from public.twitter_wallet_reservations where id=h.reservation_id for update;update public.twitter_item_holds set status='released',resolved_at=timezone('utc',now())where item_id=p_item_id;update public.twitter_wallet_reservations set remaining_micros=remaining_micros-h.amount_micros,released_micros=released_micros+h.amount_micros,status=case when remaining_micros-h.amount_micros=0 then 'released'::public.twitter_reservation_status else 'partially_settled'::public.twitter_reservation_status end where id=h.reservation_id;update public.twitter_wallets set reserved_micros=reserved_micros-h.amount_micros,version=version+1 where identity_id=r.identity_id;insert into public.twitter_reservation_events(reservation_id,organization_id,event_type,amount_micros,idempotency_key,reason)values(h.reservation_id,h.organization_id,'released',h.amount_micros,p_idempotency_key,p_reason)on conflict(idempotency_key)do nothing;return h.amount_micros;end$$;
create or replace function public.twitter_claim_publication_items(p_worker_id text,p_limit integer)returns table(item_id uuid,attempt_id uuid,organization_id uuid,profile_id uuid,connection_id uuid,content text,execute_at timestamptz,amount_micros bigint,media_set_client_key text)language plpgsql security definer set search_path=public as $$begin if coalesce(auth.role(),'')<>'service_role'then raise exception using errcode='42501';end if;return query with candidates as(select i.id from public.twitter_publication_items i where i.status in('ready','retry')and coalesce(i.next_attempt_at,i.execute_at)<=timezone('utc',now())and not exists(select 1 from public.twitter_publication_items a where a.profile_id=i.profile_id and a.status='claimed')order by coalesce(i.next_attempt_at,i.execute_at),i.id for update skip locked limit least(greatest(p_limit,1),50)),u as(update public.twitter_publication_items i set status='claimed',claimed_at=timezone('utc',now()),claimed_by=p_worker_id,attempt_count=attempt_count+1 from candidates c where i.id=c.id returning i.*),a as(insert into public.twitter_publication_attempts(organization_id,item_id,attempt_number,worker_id,idempotency_key)select u.organization_id,u.id,u.attempt_count,p_worker_id,'twitter-attempt:'||u.id::text||':'||u.attempt_count::text from u returning id,item_id)update public.twitter_item_holds h set status='active',activated_at=timezone('utc',now())from u where h.item_id=u.id returning u.id,(select a.id from a where a.item_id=u.id),u.organization_id,u.profile_id,u.connection_id,u.content,u.execute_at,u.amount_micros,u.media_set_client_key;end$$;
create or replace function public.twitter_complete_shadow_attempt(p_attempt_id uuid,p_idempotency_key text)returns jsonb language plpgsql security definer set search_path=public as $$declare a public.twitter_publication_attempts;i public.twitter_publication_items;released bigint;begin if coalesce(auth.role(),'')<>'service_role'then raise exception using errcode='42501';end if;select * into a from public.twitter_publication_attempts where id=p_attempt_id for update;if a.status='shadowed'then return jsonb_build_object('idempotentReplay',true);end if;update public.twitter_item_holds set status='reserved',activated_at=null where item_id=a.item_id and status='active';released:=public.twitter_release_item_hold(a.item_id,'shadow sem chamada externa',p_idempotency_key);update public.twitter_publication_items set status='shadowed',claimed_at=null,claimed_by=null where id=a.item_id returning * into i;update public.twitter_publication_attempts set status='shadowed',finished_at=timezone('utc',now())where id=a.id;insert into public.twitter_operation_logs(organization_id,item_id,attempt_id,connection_id,profile_id,phase,estimated_micros,settled_micros,message)values(i.organization_id,i.id,a.id,i.connection_id,i.profile_id,'shadow',i.amount_micros,0,'Shadow concluído sem chamada Zernio.');return jsonb_build_object('itemId',i.id,'releasedMicros',released,'idempotentReplay',false);end$$;
create or replace function public.twitter_cancel_items(p_organization_id uuid,p_program_id uuid,p_profile_id uuid,p_reason text,p_idempotency_key text)returns jsonb language plpgsql security definer set search_path=public as $$declare row record;released bigint:=0;affected integer:=0;pending integer:=0;begin if coalesce(auth.role(),'')<>'service_role'then raise exception using errcode='42501';end if;for row in select i.id,i.status,h.status hold_status from public.twitter_publication_items i join public.twitter_item_holds h on h.item_id=i.id where i.organization_id=p_organization_id and(p_program_id is null or i.program_id=p_program_id)and(p_profile_id is null or i.profile_id=p_profile_id)and i.status in('ready','retry','claimed','outcome_unknown')for update of i,h loop if row.status in('ready','retry')and row.hold_status='reserved'then released:=released+public.twitter_release_item_hold(row.id,p_reason,p_idempotency_key||':'||row.id);update public.twitter_publication_items set status='cancelled',cancelled_at=timezone('utc',now())where id=row.id;affected:=affected+1;else pending:=pending+1;end if;end loop;return jsonb_build_object('affectedItems',affected,'releasedMicros',released,'pendingReconciliation',pending);end$$;
create or replace function public.twitter_record_worker_heartbeat(p_worker_name text,p_worker_id text,p_mode text,p_metadata jsonb default '{}')returns void language plpgsql security definer set search_path=public as $$begin if coalesce(auth.role(),'')<>'service_role'then raise exception using errcode='42501';end if;insert into public.twitter_worker_heartbeats(worker_name,worker_id,mode,last_seen_at,metadata)values(p_worker_name,p_worker_id,p_mode,timezone('utc',now()),coalesce(p_metadata,'{}'))on conflict(worker_name)do update set worker_id=excluded.worker_id,mode=excluded.mode,last_seen_at=excluded.last_seen_at,metadata=excluded.metadata,updated_at=timezone('utc',now());end$$;
alter table public.twitter_item_holds enable row level security;alter table public.twitter_publication_attempts enable row level security;alter table public.twitter_operation_logs enable row level security;alter table public.twitter_worker_heartbeats enable row level security;alter table public.twitter_circuit_breakers enable row level security;
create policy twitter_holds_select_member on public.twitter_item_holds for select to authenticated using(public.is_organization_member(organization_id));create policy twitter_attempts_select_member on public.twitter_publication_attempts for select to authenticated using(public.is_organization_member(organization_id));create policy twitter_logs_select_member on public.twitter_operation_logs for select to authenticated using(public.is_organization_member(organization_id));
revoke all on table public.twitter_item_holds,public.twitter_publication_attempts,public.twitter_operation_logs,public.twitter_worker_heartbeats,public.twitter_circuit_breakers from anon,authenticated;grant select on public.twitter_item_holds,public.twitter_publication_attempts,public.twitter_operation_logs to authenticated;grant select,insert,update,delete on public.twitter_item_holds,public.twitter_publication_attempts,public.twitter_operation_logs,public.twitter_worker_heartbeats,public.twitter_circuit_breakers to service_role;
revoke all on function public.twitter_release_item_hold(uuid,text,text),public.twitter_claim_publication_items(text,integer),public.twitter_complete_shadow_attempt(uuid,text),public.twitter_cancel_items(uuid,uuid,uuid,text,text),public.twitter_record_worker_heartbeat(text,text,text,jsonb)from public,anon,authenticated;grant execute on function public.twitter_release_item_hold(uuid,text,text),public.twitter_claim_publication_items(text,integer),public.twitter_complete_shadow_attempt(uuid,text),public.twitter_cancel_items(uuid,uuid,uuid,text,text),public.twitter_record_worker_heartbeat(text,text,text,jsonb)to service_role;
